// Package schema turns Hyprland's generated Lua stub (hl.meta.lua) into a
// machine-readable description of every configuration option, dispatcher,
// event and spec table, so the UI can render schema-driven forms.
//
// The stub is generated by Hyprland itself (scripts/generateLuaStubs.py), which
// makes it the most accurate available source of truth: it always matches the
// installed compositor. HyprMod prefers the installed stub and falls back to an
// embedded copy when it is absent.
package schema

import (
	_ "embed"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/juniorgs/hyprmod/internal/config"
)

//go:embed stub/hl.meta.lua
var embeddedStub string

// Common locations for the installed stub, in preference order.
var stubLocations = []string{
	"/usr/share/hypr/stubs/hl.meta.lua",
	"/usr/local/share/hypr/stubs/hl.meta.lua",
}

// Field is a table field parsed from a stub class.
type Field struct {
	Name     string `json:"name"`
	Type     string `json:"type"`
	Optional bool   `json:"optional"`
}

// Option is a node in the configuration option tree. Nodes with Children are
// table sections; nodes without are leaf options.
type Option struct {
	Name     string           `json:"name"`
	Path     string           `json:"path"`
	Kind     config.ValueKind `json:"kind"`
	Raw      string           `json:"raw"`
	Children []*Option        `json:"children,omitempty"`
}

// IsSection reports whether the node is a table (has children).
func (o *Option) IsSection() bool { return len(o.Children) > 0 }

// Schema is the parsed stub.
type Schema struct {
	Sections    []*Option
	Dispatchers []string
	Events      []string
	Specs       map[string][]Field
	Source      string // path of the stub that was loaded, or "embedded"
}

// Load reads the installed stub when available and falls back to the embedded
// copy. It never fails: a parse error on the installed stub also falls back.
func Load() *Schema {
	for _, p := range stubLocations {
		if b, err := os.ReadFile(p); err == nil {
			if s, err := Parse(string(b)); err == nil {
				s.Source = p
				return s
			}
		}
	}
	s, err := Parse(embeddedStub)
	if err != nil {
		// The embedded stub is compile-time verified by tests; reaching here
		// means a corrupt build. Return an empty schema rather than panicking.
		return &Schema{Specs: map[string][]Field{}, Source: "embedded"}
	}
	s.Source = "embedded"
	return s
}

// LoadFrom parses a stub from an explicit path.
func LoadFrom(path string) (*Schema, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	s, err := Parse(string(b))
	if err != nil {
		return nil, err
	}
	s.Source = path
	return s, nil
}

// FallbackSearchRoots returns directories that may contain hl.meta.lua, used by
// the app when probing the system.
func FallbackSearchRoots() []string {
	var out []string
	for _, p := range stubLocations {
		out = append(out, filepath.Dir(p))
	}
	return out
}

// Parse builds a Schema from stub source text.
func Parse(src string) (*Schema, error) {
	classes := map[string][]Field{}
	aliases := map[string][]string{}
	var curClass, curAlias string

	for _, line := range strings.Split(src, "\n") {
		line = strings.TrimSpace(line)
		switch {
		case strings.HasPrefix(line, "---@class "):
			curClass = strings.TrimSpace(strings.TrimPrefix(line, "---@class "))
			curAlias = ""
			if _, ok := classes[curClass]; !ok {
				classes[curClass] = nil
			}
		case strings.HasPrefix(line, "---@alias "):
			curAlias = strings.TrimSpace(strings.TrimPrefix(line, "---@alias "))
			curClass = ""
			if _, ok := aliases[curAlias]; !ok {
				aliases[curAlias] = nil
			}
		case strings.HasPrefix(line, "---@field "):
			if curClass == "" {
				continue
			}
			f, ok := parseField(strings.TrimSpace(strings.TrimPrefix(line, "---@field ")))
			if !ok {
				continue
			}
			classes[curClass] = append(classes[curClass], f)
		case strings.HasPrefix(line, "---|"):
			if curAlias == "" {
				continue
			}
			v := strings.TrimSpace(strings.TrimPrefix(line, "---|"))
			v = strings.Trim(v, `"`)
			if v != "" && !strings.HasPrefix(v, "[") {
				aliases[curAlias] = append(aliases[curAlias], v)
			}
		case line == "" || !strings.HasPrefix(line, "---"):
			// Any other annotation or code line ends the current doc block.
			if !strings.HasPrefix(line, "---") && line != "" {
				// keep curClass/curAlias: stub groups annotations per class only
			}
		}
	}

	s := &Schema{Specs: map[string][]Field{}}
	s.Sections = buildOptions(classes, "HL.ConfigOpt", "")
	s.Dispatchers = buildDispatchers(classes)
	s.Events = aliases["HL.EventName"]
	sort.Strings(s.Dispatchers)
	sort.Strings(s.Events)
	for name, fields := range classes {
		if isSpecClass(name) {
			s.Specs[strings.TrimPrefix(name, "HL.")] = fields
		}
	}
	return s, nil
}

func parseField(s string) (Field, bool) {
	// Formats: `name? type` or `name type`. Types with spaces (fun(...)) are
	// skipped by callers where relevant.
	var name, typ string
	if i := strings.IndexAny(s, " \t"); i >= 0 {
		name, typ = s[:i], strings.TrimSpace(s[i+1:])
	} else {
		name = s
	}
	name = strings.TrimSpace(name)
	f := Field{Name: name, Type: typ}
	if strings.HasSuffix(name, "?") {
		f.Name = strings.TrimSuffix(name, "?")
		f.Optional = true
	}
	if f.Name == "" {
		return Field{}, false
	}
	return f, true
}

// buildOptions recursively expands a `HL.ConfigOpt[.Sub]` class into the option
// tree. prefix is the dotted path accumulated so far ("" for root sections).
func buildOptions(classes map[string][]Field, className, prefix string) []*Option {
	fields := classes[className]
	var out []*Option
	for _, f := range fields {
		path := f.Name
		if prefix != "" {
			path = prefix + "." + f.Name
		}
		if strings.HasPrefix(f.Type, "HL.ConfigOpt.") {
			childClass := f.Type
			children := buildOptions(classes, childClass, path)
			out = append(out, &Option{Name: f.Name, Path: path, Children: children, Raw: f.Type})
			continue
		}
		kind := Classify(f.Name, f.Type)
		out = append(out, &Option{Name: f.Name, Path: path, Kind: kind, Raw: f.Type})
	}
	sort.SliceStable(out, func(i, j int) bool { return out[i].Name < out[j].Name })
	return out
}

func buildDispatchers(classes map[string][]Field) []string {
	var out []string
	for name, fields := range classes {
		if !strings.HasPrefix(name, "HL.Dsp") {
			continue
		}
		prefix := dispatcherPrefix(name)
		for _, f := range fields {
			if !strings.HasPrefix(f.Type, "fun(") {
				continue // nested namespace field
			}
			if prefix == "" {
				out = append(out, f.Name)
			} else {
				out = append(out, prefix+"."+f.Name)
			}
		}
	}
	return dedupe(out)
}

// dispatcherPrefix maps HL.DspNamespace -> "" and HL.DspWindowNamespace ->
// "window", HL.DspCursorNamespace -> "cursor".
func dispatcherPrefix(className string) string {
	trimmed := strings.TrimPrefix(className, "HL.Dsp")
	trimmed = strings.TrimSuffix(trimmed, "Namespace")
	if trimmed == "" {
		return ""
	}
	return strings.ToLower(trimmed[:1]) + trimmed[1:]
}

func isSpecClass(name string) bool {
	base := strings.TrimPrefix(name, "HL.")
	switch base {
	case "MonitorSpec", "WindowRuleSpec", "LayerRuleSpec", "WorkspaceRuleSpec",
		"Keybind", "LayerRule", "WindowRule", "WorkspaceRule", "Monitor",
		"GestureSpec", "DeviceSpec", "BindOptions", "TimerOptions",
		"PermissionSpec":
		return true
	}
	return false
}

func dedupe(in []string) []string {
	seen := map[string]bool{}
	var out []string
	for _, s := range in {
		if seen[s] {
			continue
		}
		seen[s] = true
		out = append(out, s)
	}
	return out
}
